import type { Metadata } from "next";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import ScrollReveal from "@/components/ScrollReveal";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: {
    default: site.navbar.seo.title,
    template: `%s | ${site.navbar.brand.name}`,
  },
  description: site.navbar.seo.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      data-scroll-behavior="smooth"
      // Root font size: 16px, and from 1024px it follows the viewport width (16px at 1920px) so the 1920px design
      // scales as a whole. Capped at 16px: wider screens and a zoomed-out browser keep the 1920px design, centred.
      // Tailwind v4 leaves buttons on the default cursor, so everything clickable gets the pointer
      // (in :where(), so a cursor-* class on the element still wins).
      className={`${fontVariables} h-full scroll-smooth text-[16px] antialiased motion-reduce:scroll-auto xl:text-[length:min(16px,calc(100vw/120))] [:where(&)_:where(a[href],button:not(:disabled),select,[role=button],[role=tab],summary)]:cursor-pointer`}
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
      </head>
      <body className="min-h-full bg-backdrop font-poppins text-ink [&_img]:select-none">
        {/*
          The whole site sits in one frame, at most 1920px wide and centred. Up to 1920px it fills the screen, so
          nothing changes; on wider screens or when the browser is zoomed out the page stays in the middle with
          equal space on both sides instead of stretching.
          --section-gap is the one vertical gap between every page section (and before the footer):
          64px mobile, 80px tablet, then 9rem of the scaled desktop design (144px at 1920px).
        */}
        <div className="mx-auto flex min-h-screen w-full max-w-[1920px] flex-col overflow-x-clip bg-page [--section-gap:4rem] md:[--section-gap:5rem] xl:[--section-gap:9rem]">
          <Navbar data={site.navbar} />
          <main className="flex flex-1 flex-col gap-(--section-gap)">
            <ScrollToTop>
              {children}
              <ScrollReveal />
            </ScrollToTop>
          </main>
          <Footer data={site.footer} />
        </div>
      </body>
    </html>
  );
}
